using System.Security.Claims;
using System.Text.Json;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Primitives;
using Npgsql;
using Xunit;
namespace Poseidon.Tests;
[Collection("PostgreSQL schema")]
public class CertificateSecurityTests {
 static JsonElement Json(object value)=>JsonSerializer.SerializeToElement(value);
 static ClaimsPrincipal User(Session s,bool write=true,bool cert=true,bool inventory=false)=>new(new ClaimsIdentity(new[]{new Claim("sub",s.Subject),new Claim("synthetic","true"),new Claim("tenant_id",s.TenantId.ToString()),new Claim("company_id",s.CompanyId.ToString())}.Concat(s.VesselIds.Select(v=>new Claim("vessel_id",v.ToString()))).Concat(write?[new Claim("permission","draft:write")]:Array.Empty<Claim>()).Concat(cert?[new Claim("permission","certificate:manage")]:Array.Empty<Claim>()).Concat(inventory?[new Claim("permission","inventory:manage")]:Array.Empty<Claim>()),"Synthetic"));
 static async Task Fault(int status,Func<Task> call){var e=await Assert.ThrowsAsync<ApiFault>(call);Assert.Equal(status,e.Status);}
 static async Task<Guid> Parent(DraftStore store,Session scope){var d=await store.InventoryWrite(User(scope),null,"create",null,Json(new{data=new{name="Synthetic scoped parent"}}),Guid.NewGuid().ToString(),"test",default);return d.Id;}
 [PostgresFact] public async Task Scope_capabilities_original_replay_permission_and_atomic_races(){
  await using var source=NpgsqlDataSource.Create(TestDatabase.Connection);var store=new DraftStore(source);await store.Migrate(default);await store.Seed(default);var scope=SyntheticIdentity.Fixtures["certificate-manager"];var user=User(scope);var parent=await Parent(store,scope);
  var data=new{vessel_id=parent.ToString(),type="Synthetic",issuer="Declared"};var item=await store.CertificateWrite(user,null,"create",null,Json(new{data}),Guid.NewGuid().ToString(),"test",default);
  await Fault(403,()=>store.CertificateWrite(User(scope,true,false),item.Id,"record",item.Version,Json(new{}),Guid.NewGuid().ToString(),"test",default));
  await Fault(403,()=>store.CertificateWrite(User(scope,true,false,true),item.Id,"record",item.Version,Json(new{}),Guid.NewGuid().ToString(),"test",default));
  var key=Guid.NewGuid().ToString();var replies=await Task.WhenAll(Enumerable.Range(0,4).Select(_=>store.CertificateWrite(user,item.Id,"record",item.Version,Json(new{}),key,"test",default)));Assert.All(replies,x=>Assert.Equal(2,x.Version));
  var recorded=replies[0];var metadataKey=Guid.NewGuid().ToString();var change=Json(new{data,reason="Private correction"});var changed=await store.CertificateWrite(user,item.Id,"metadata",recorded.Version,change,metadataKey,"test",default);
  await store.CertificateWrite(user,item.Id,"reopen",changed.Version,Json(new{reason="Private reopen"}),Guid.NewGuid().ToString(),"test",default);
  await Fault(403,()=>store.CertificateWrite(User(scope,true,false),item.Id,"metadata",recorded.Version,change,metadataKey,"test",default));
  var reader=scope with{Subject="synthetic-certificate-reader",VesselIds=[parent]};Assert.Equal(item.Id,(await store.CertificateGet(reader,item.Id,default)).Id);
  await Fault(403,()=>store.CertificateWrite(User(reader,false,false),item.Id,"metadata",4,Json(new{data}),Guid.NewGuid().ToString(),"test",default));
  foreach(var denied in new[]{reader with{VesselIds=[]},reader with{CompanyId=Guid.NewGuid()},reader with{TenantId=Guid.NewGuid()}}){await Fault(404,()=>store.CertificateGet(denied,item.Id,default));await Fault(404,()=>store.CertificateWrite(User(denied),item.Id,"record",4,Json(new{}),key,"test",default));}
  var current=await store.CertificateGet(scope,item.Id,default);async Task<int> Race(string number){try{await store.CertificateWrite(user,item.Id,"metadata",current.Version,Json(new{data=new{vessel_id=parent.ToString(),certificate_no=number}}),Guid.NewGuid().ToString(),"test",default);return 200;}catch(ApiFault e){return e.Status;}}
  var results=await Task.WhenAll(Race("first"),Race("second"));Assert.Single(results,x=>x==200);Assert.Single(results,x=>x==412);
  await using var c=await source.OpenConnectionAsync();await using var q=new NpgsqlCommand("SELECT count(*) FROM audit_events WHERE entity_id=@id",c);q.Parameters.AddWithValue("id",item.Id);Assert.Equal(5L,await q.ExecuteScalarAsync());
 }
 [PostgresFact] public async Task Scoped_paging_over_500_literal_query_and_cursor_context_isolation(){
  await using var source=NpgsqlDataSource.Create(TestDatabase.Connection);var store=new DraftStore(source);await store.Migrate(default);await store.Seed(default);var scope=SyntheticIdentity.Fixtures["certificate-manager"];var parent=await Parent(store,scope);await using var c=await source.OpenConnectionAsync();var marker="Literal %_\\ "+Guid.NewGuid();
  await using(var seed=new NpgsqlCommand("INSERT INTO drafts(tenant_id,id,company_id,kind,vessel_id,owner_subject,version,data) SELECT @tenant,gen_random_uuid(),@company,'certificates',@parent,'not-the-vessel-owner',1,jsonb_build_object('vessel_id',@parent::text,'type',@marker,'issuer','Declared','expiry','2026-10-28') FROM generate_series(1,601)",c)){seed.Parameters.AddWithValue("tenant",scope.TenantId);seed.Parameters.AddWithValue("company",scope.CompanyId);seed.Parameters.AddWithValue("parent",parent);seed.Parameters.AddWithValue("marker",marker);await seed.ExecuteNonQueryAsync();}
  var values=new Dictionary<string,StringValues>{{"q",marker},{"vessel_id",parent.ToString()},{"dateBucket","WITHIN_30_DAYS"},{"pageSize","100"}};var today=new DateOnly(2026,10,27);List<Guid> ids=[];string? firstCursor=null;
  do{var page=await store.CertificateList(scope,CertificateBrowse.Parse(new QueryCollection(values),scope,today),default);ids.AddRange(page.Items.Select(x=>x.Id));if(page.NextCursor is null)break;firstCursor??=page.NextCursor;values["cursor"]=page.NextCursor;}while(true);
  Assert.Equal(601,ids.Count);Assert.Equal(601,ids.Distinct().Count());values["cursor"]=firstCursor;values["dateBucket"]="TODAY";Assert.Throws<ApiFault>(()=>CertificateBrowse.Parse(new QueryCollection(values),scope,today));values["dateBucket"]="WITHIN_30_DAYS";Assert.Throws<ApiFault>(()=>CertificateBrowse.Parse(new QueryCollection(values),scope with{Subject="other"},today));
  foreach(var invalid in new Dictionary<string,StringValues>[]{new Dictionary<string,StringValues>{{"pageSize","101"}},new(){{"q",new string('x',101)}},new(){{"unknown","x"}},new(){{"dateBucket","VALID"}},new(){{"asOfDate","2025-01-01"}},new(){{"cursor",new string('x',10000)}},new(){{"q",new StringValues(["a","b"])}}})Assert.Throws<ApiFault>(()=>CertificateBrowse.Parse(new QueryCollection(invalid),scope,today));
  var hidden=scope with{Subject="same-company-ungranted"};Assert.Empty((await store.CertificateList(hidden,CertificateBrowse.Parse(new QueryCollection(),hidden,today),default)).Items);
 }
 [PostgresFact] public async Task Certificate_history_redacts_values_unknown_actions_and_rechecks_parent_access(){
  await using var source=NpgsqlDataSource.Create(TestDatabase.Connection);var store=new DraftStore(source);await store.Migrate(default);await store.Seed(default);var scope=SyntheticIdentity.Fixtures["certificate-manager"];var parent=await Parent(store,scope);var row=await store.CertificateWrite(User(scope),null,"create",null,Json(new{data=new{vessel_id=parent.ToString(),notes="PRIVATE ORIGINAL"}}),Guid.NewGuid().ToString(),"test",default);
  await using var c=await source.OpenConnectionAsync();await using(var insert=new NpgsqlCommand("INSERT INTO audit_events(id,tenant_id,company_id,entity_id,vessel_id,actor,action,after_data,version,correlation_id,restricted_metadata) VALUES(@event,@tenant,@company,@id,@parent,@actor,'PRIVATE UNKNOWN ACTION','{\"unknown_secret_key\":\"PRIVATE VALUE\",\"notes\":\"PRIVATE NOTES\"}',2,'PRIVATE CORRELATION','{\"reason\":\"PRIVATE REASON\"}')",c)){insert.Parameters.AddWithValue("event",Guid.NewGuid());insert.Parameters.AddWithValue("tenant",scope.TenantId);insert.Parameters.AddWithValue("company",scope.CompanyId);insert.Parameters.AddWithValue("id",row.Id);insert.Parameters.AddWithValue("parent",parent);insert.Parameters.AddWithValue("actor",scope.Subject);await insert.ExecuteNonQueryAsync();}
  var reader=scope with{Subject="other-subject",VesselIds=[parent]};var query=new QueryCollection(new Dictionary<string,StringValues>{{"pageSize","1"}});var page=await store.CertificateHistory(reader,row.Id,CertificateHistoryQuery.Parse(query,reader,row.Id),default);Assert.Single(page.Items);Assert.Equal("OTHER",page.Items[0].ActorRelation);
  var serialized=JsonSerializer.Serialize(page);foreach(var value in new[]{"PRIVATE","unknown_secret_key","synthetic-certificate-manager","reason","before_data","after_data"})Assert.DoesNotContain(value,serialized);
  var continuation=new QueryCollection(new Dictionary<string,StringValues>{{"pageSize","1"},{"cursor",page.NextCursor}});Assert.Throws<ApiFault>(()=>CertificateHistoryQuery.Parse(continuation,reader,Guid.NewGuid()));
  var revoked=reader with{VesselIds=[]};await Fault(404,()=>store.CertificateHistory(revoked,row.Id,CertificateHistoryQuery.Parse(new QueryCollection(),revoked,row.Id),default));
 }
 [PostgresFact] public async Task Audit_failure_rolls_back_certificate_command_and_retry_commits_once(){
  await using var source=NpgsqlDataSource.Create(TestDatabase.Connection);var store=new DraftStore(source);await store.Migrate(default);await store.Seed(default);var scope=SyntheticIdentity.Fixtures["certificate-manager"];var user=User(scope);var parent=await Parent(store,scope);var row=await store.CertificateWrite(user,null,"create",null,Json(new{data=new{vessel_id=parent.ToString(),type="Synthetic",issuer="Declared"}}),Guid.NewGuid().ToString(),"test",default);var key=Guid.NewGuid().ToString();var trigger="certificate_fail_"+Guid.NewGuid().ToString("N");await using var c=await source.OpenConnectionAsync();
  await using(var ddl=new NpgsqlCommand($"CREATE FUNCTION {trigger}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.entity_id='{row.Id}' AND NEW.action='CERTIFICATE_RECORDED' THEN RAISE EXCEPTION 'synthetic certificate audit failure'; END IF; RETURN NEW; END $$; CREATE TRIGGER {trigger} BEFORE INSERT ON audit_events FOR EACH ROW EXECUTE FUNCTION {trigger}();",c))await ddl.ExecuteNonQueryAsync();
  try{await Assert.ThrowsAsync<PostgresException>(()=>store.CertificateWrite(user,row.Id,"record",row.Version,Json(new{}),key,"test",default));var unchanged=await store.CertificateGet(scope,row.Id,default);Assert.Equal(1,unchanged.Version);Assert.Equal("DRAFT",unchanged.AdminState);await using var q=new NpgsqlCommand("SELECT count(*) FROM idempotency WHERE key=@key",c);q.Parameters.AddWithValue("key",key);Assert.Equal(0L,await q.ExecuteScalarAsync());}
  finally{await using var drop=new NpgsqlCommand($"DROP TRIGGER {trigger} ON audit_events;DROP FUNCTION {trigger}();",c);await drop.ExecuteNonQueryAsync();}
  Assert.Equal(2,(await store.CertificateWrite(user,row.Id,"record",row.Version,Json(new{}),key,"test",default)).Version);
 }
}
